'use client'

import { useEffect } from 'react'

/**
 * Registers the PWA service worker (generated by next-pwa at build time as /sw.js).
 * next-pwa's own `register: true` injection does not run for the App Router, so without this the worker
 * is never installed - which also means web push, offline caching and "install app" cannot work.
 * Production only: in development the worker is disabled.
 */
export default function ServiceWorkerRegister() {
  useEffect(() => {
    if (process.env.NODE_ENV !== 'production' || !('serviceWorker' in navigator)) return

    const register = () => {
      navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch((error) => {
        console.warn('[pwa] service worker registration failed:', error)
      })
    }

    if (document.readyState === 'complete') register()
    else {
      window.addEventListener('load', register, { once: true })
      return () => window.removeEventListener('load', register)
    }
  }, [])

  return null
}
